"""Schemas for fixture inputs, the generated baseline manifest, and the materialized snapshot.

These files are the project's shared test oracle (roadmap §5):

* hand-labeled, human-editable, reviewed: ``ExpectedFindingsFile``, ``CandidateIndexFile``
* generated by ``tools/fixturectl.py``: ``BaselinesManifest``, ``FixtureSnapshot``
* fixture configuration: ``FixtureHistory``

Nothing in this module may derive expectations from a model's output. Candidate scores
and labels are hand-written fixture values for the fake provider and for retrieval
evaluation (AI-05); they are never presented as measured model quality.
"""

from __future__ import annotations

from datetime import datetime
from typing import Literal

from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator

from app.domain.enums import (
    FindingStatus,
    FindingType,
    RelationType,
    ReviewState,
    RuleId,
    Severity,
)
from app.domain.models import (
    ARTIFACT_ID_PATTERN,
    Artifact,
    AssuranceFinding,
    TraceLink,
    VerificationEvidence,
    _require_aware,
    validate_link_partition,
)


class _StrictModel(BaseModel):
    model_config = ConfigDict(extra="forbid")


class _FrozenModel(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)


# --------------------------------------------------------------------------------------
# Fixture configuration and generated provenance
# --------------------------------------------------------------------------------------


class FixtureCommitSpec(_FrozenModel):
    """One commit in the generated fixture history, in order."""

    id: str = Field(
        pattern=r"^[a-z0-9-]+$", description="Logical id, referenced by {{COMMIT:<id>}} tokens."
    )
    message: str = Field(min_length=1)
    date: datetime = Field(description="Authored and committed date (must be timezone-aware).")
    overlay: str = Field(
        min_length=1,
        description="Directory whose contents are copied over the work tree before committing "
        "(relative to the fixture directory).",
    )
    tags: list[str] = Field(
        default_factory=list, description="Lightweight tags created on this commit."
    )

    @field_validator("date")
    @classmethod
    def _aware(cls, value: datetime) -> datetime:
        return _require_aware(value)


class FixtureHistory(_StrictModel):
    """``fixtures/<fixture>/history.json`` — declarative fixture Git history."""

    schema_version: str
    fixture: str
    commits: list[FixtureCommitSpec] = Field(min_length=1)

    @model_validator(mode="after")
    def _unique(self) -> FixtureHistory:
        ids = [c.id for c in self.commits]
        if len(ids) != len(set(ids)):
            raise ValueError("commit ids must be unique")
        tags = [t for c in self.commits for t in c.tags]
        if len(tags) != len(set(tags)):
            raise ValueError("tags must be unique")
        if not tags:
            raise ValueError("the fixture history must define at least one tag")
        return self


class BaselineCommit(_FrozenModel):
    id: str
    commit: str
    date: datetime
    message: str
    tags: list[str]


class BaselinesManifest(_FrozenModel):
    """``fixtures/<fixture>/expected/baselines.json`` — generated, committed, drift-checked.

    Reproducibility contract: the fixture history is built with fixed author/committer
    identities, dates, and messages, so these SHAs are identical on every machine and git
    version. A change to fixture content changes them, which fails the drift test and
    forces a deliberate regeneration.
    """

    schema_version: str
    fixture: str
    generated_by: str
    commits: list[BaselineCommit]
    tags: dict[str, str] = Field(description="tag name -> commit SHA")


# --------------------------------------------------------------------------------------
# Hand-labeled oracle
# --------------------------------------------------------------------------------------


class ChangeSummary(_FrozenModel):
    """Hand-labeled description of what changed between baselines."""

    changed_paths: list[str]
    changed_artifact_ids: list[str]
    unchanged_artifact_ids: list[str]

    @field_validator("changed_paths", "changed_artifact_ids", "unchanged_artifact_ids")
    @classmethod
    def _sorted_unique(cls, value: list[str]) -> list[str]:
        return sorted(set(value))


class ExpectedFinding(_FrozenModel):
    """Hand-labeled expectation for one finding. ``finding_id`` and revisions are derived."""

    rule_id: RuleId
    finding_type: FindingType
    severity: Severity
    status: FindingStatus = FindingStatus.OPEN
    artifact_ids: list[str] = Field(min_length=1)
    evidence_ids: list[str] = Field(default_factory=list)
    explanation: str = Field(min_length=1)

    @field_validator("artifact_ids")
    @classmethod
    def _a(cls, value: list[str]) -> list[str]:
        return sorted(set(value))

    @field_validator("evidence_ids")
    @classmethod
    def _e(cls, value: list[str]) -> list[str]:
        return sorted(set(value))


class ExpectedFindingsFile(_FrozenModel):
    """``fixtures/<fixture>/expected/baseline-<x>.json`` — the rule oracle for one baseline."""

    schema_version: str
    fixture: str
    baseline: str
    notes: list[str] = Field(default_factory=list)
    healthy_artifact_ids: list[str] = Field(
        default_factory=list,
        description="Artifacts that must have no finding at this baseline (negative expectation).",
    )
    change_summary: ChangeSummary | None = Field(
        default=None, description="Present when this baseline is compared against a predecessor."
    )
    findings: list[ExpectedFinding]

    @field_validator("healthy_artifact_ids")
    @classmethod
    def _h(cls, value: list[str]) -> list[str]:
        return sorted(set(value))


class CandidateLabel(_FrozenModel):
    """One hand-labeled candidate proposal for the fake discovery index."""

    source_id: str = Field(pattern=ARTIFACT_ID_PATTERN)
    target_id: str = Field(pattern=ARTIFACT_ID_PATTERN)
    proposed_relation_type: RelationType
    score: float = Field(ge=0.0, le=1.0)
    rationale: str | None = None
    label: Literal["positive", "negative"] = Field(
        default="positive",
        description="Evaluation label for AI-05. Not visible in API responses and never used to "
        "filter retrieval output: the system must be able to return a wrong suggestion for a "
        "reviewer to reject.",
    )


class CandidateIndexFile(_FrozenModel):
    """``fixtures/<fixture>/expected/candidate-links.json`` — fake-provider index + AI-05 labels."""

    schema_version: str
    fixture: str
    provider: str = Field(min_length=1)
    model_version: str = Field(min_length=1)
    candidates: list[CandidateLabel]

    @model_validator(mode="after")
    def _unique_pairs(self) -> CandidateIndexFile:
        pairs = [(c.source_id, c.target_id, c.proposed_relation_type) for c in self.candidates]
        if len(pairs) != len(set(pairs)):
            raise ValueError("candidate (source, target, relation) triples must be unique")
        return self


# --------------------------------------------------------------------------------------
# Generated snapshot (mock store data)
# --------------------------------------------------------------------------------------


class BaselineSnapshot(_FrozenModel):
    """All facts known at one baseline: artifacts, links, evidence."""

    baseline: str = Field(description="Fixture baseline name (tag).")
    commit: str = Field(description="Resolved commit SHA of the baseline.")
    artifacts: list[Artifact]
    accepted_links: list[TraceLink]
    proposed_links: list[TraceLink]
    evidence: list[VerificationEvidence]

    @model_validator(mode="after")
    def _link_states(self) -> BaselineSnapshot:
        validate_link_partition(accepted=self.accepted_links, proposed=self.proposed_links)
        ids = [a.artifact_id for a in self.artifacts]
        if len(ids) != len(set(ids)):
            raise ValueError("artifact ids must be unique within a baseline snapshot")
        return self

    def artifact(self, artifact_id: str) -> Artifact | None:
        return next((a for a in self.artifacts if a.artifact_id == artifact_id), None)


class FixtureSnapshot(_FrozenModel):
    """``fixtures/api-responses/snapshot.json`` — the fixture-backed read model."""

    schema_version: str
    fixture: str
    generated_by: str
    baselines: list[BaselineSnapshot] = Field(min_length=1)

    @model_validator(mode="after")
    def _unique(self) -> FixtureSnapshot:
        names = [b.baseline for b in self.baselines]
        if len(names) != len(set(names)):
            raise ValueError("baseline names must be unique")
        commits = [b.commit for b in self.baselines]
        if len(commits) != len(set(commits)):
            raise ValueError("baseline commits must be unique")
        return self


class FixtureEvidenceFile(_FrozenModel):
    """``evidence/verification-runs.json`` inside a fixture repository (CI-recorded runs)."""

    schema_version: str
    repository: str = Field(min_length=1)
    runs: list[VerificationEvidence]


class FixtureLinkFile(_FrozenModel):
    """``evidence/accepted-links.json`` and ``evidence/proposed-links.json``.

    One review state per file, enforced by the model: accepted facts and pending proposals
    must not share a file, so no reader can mistake one for the other.
    """

    schema_version: str
    repository: str = Field(min_length=1)
    review_state: ReviewState
    links: list[TraceLink]

    @model_validator(mode="after")
    def _state_matches(self) -> FixtureLinkFile:
        mismatched = [link.link_id for link in self.links if link.review_state != self.review_state]
        if mismatched:
            raise ValueError(
                f"file declares review_state={self.review_state} but contains links in another "
                f"state: {', '.join(mismatched)}"
            )
        return self

    @model_validator(mode="after")
    def _unique_ids(self) -> FixtureLinkFile:
        identifiers = [link.link_id for link in self.links]
        if len(identifiers) != len(set(identifiers)):
            raise ValueError("link ids must be unique within a link file")
        return self


class MaterializedFindings(_FrozenModel):
    """``fixtures/api-responses/findings.<baseline>.json`` — sample findings response."""

    schema_version: str
    baseline: str
    findings: list[AssuranceFinding]
